"""Evaluate BEVFusion on a config generated by make_weather_config.py.

tools/test.py loads configs through torchpack, which expects the YAML config
hierarchy. make_weather_config.py writes an already-resolved mmcv config.py, so
this script loads it with mmcv.Config.fromfile and otherwise mirrors
tools/test.py on a single GPU (no torchpack launcher needed).

Writes to --out-dir (default: the config's directory):
  metrics.json        all nuScenes metrics plus the run settings
  nusc/               nuScenes devkit outputs (results_nusc.json, metrics_summary.json)
  results.pkl         raw predictions (only with --save-results)

Example:
  python tools/weather_eval/run_eval.py \
    work_dirs/weather_full/fog_060/config.py pretrained/bevfusion-det.pth
"""
import argparse
from collections import Counter
import json
from pathlib import Path
import sys
import time

REPO_ROOT = Path(__file__).resolve().parents[2]
if str(REPO_ROOT) not in sys.path:
  sys.path.insert(0, str(REPO_ROOT))

import mmcv  # noqa: E402
import torch  # noqa: E402
from mmcv import Config  # noqa: E402
from mmcv.parallel import MMDataParallel  # noqa: E402
from mmcv.runner import load_checkpoint, wrap_fp16_model  # noqa: E402
from mmdet.apis import set_random_seed  # noqa: E402

from mmdet3d.apis import single_gpu_test  # noqa: E402
from mmdet3d.datasets import build_dataloader, build_dataset  # noqa: E402
from mmdet3d.models import build_model  # noqa: E402


def parse_args():
  parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
  parser.add_argument("config", help="Generated config.py")
  parser.add_argument("checkpoint", help="BEVFusion checkpoint (.pth)")
  parser.add_argument(
      "--out-dir", default=None, help="Output directory (default: config's dir)"
  )
  parser.add_argument(
      "--workers", type=int, default=4, help="Dataloader workers (default: 4)"
  )
  parser.add_argument("--seed", type=int, default=0, help="Torch/numpy seed")
  parser.add_argument(
      "--save-results", action="store_true", help="Also write raw results.pkl"
  )
  parser.add_argument(
      "--skip-existing",
      action="store_true",
      help="Do nothing if metrics.json already exists in the output directory",
  )
  return parser.parse_args()


def checkpoint_signature(path):
  """(size, mtime) of the checkpoint file, following symlinks (latest.pth)."""
  st = Path(path).resolve().stat()
  return [int(st.st_size), int(st.st_mtime)]


def is_up_to_date(metrics_path, checkpoint):
  """True if metrics_path exists and was produced from this checkpoint file.

  Runs recorded before signatures were stored count as up to date.
  """
  metrics_path = Path(metrics_path)
  if not metrics_path.exists():
    return False
  recorded = json.loads(metrics_path.read_text()).get("checkpoint_signature")
  return recorded is None or recorded == checkpoint_signature(checkpoint)


def _weather_step(pipeline):
  for op in pipeline or []:
    if isinstance(op, dict) and op.get("type") == "WeatherDegradation":
      return op
  return None


def gt_class_counts(dataset):
  """Ground-truth boxes per class, counting only boxes the nuScenes eval keeps.

  valid_flag marks boxes with at least one LiDAR or radar point; the devkit
  drops the rest.
  """
  counts = Counter()
  for info in dataset.data_infos:
    names = info.get("gt_names", [])
    flags = info.get("valid_flag", [True] * len(names))
    counts.update(n for n, ok in zip(names, flags) if ok)
  return {c: int(counts.get(c, 0)) for c in dataset.CLASSES}


def per_class_ap(summary_path):
  """Per-class AP averaged over distance thresholds, from the devkit summary."""
  summary = json.loads(Path(summary_path).read_text())
  return {k: float(v) for k, v in summary["mean_dist_aps"].items()}


def main():
  args = parse_args()
  cfg_path = Path(args.config)
  out_dir = Path(args.out_dir) if args.out_dir else cfg_path.parent
  out_dir.mkdir(parents=True, exist_ok=True)
  metrics_path = out_dir / "metrics.json"
  if not Path(args.checkpoint).exists():
    raise SystemExit(f"Checkpoint not found: {args.checkpoint} (still training?)")
  if args.skip_existing and is_up_to_date(metrics_path, args.checkpoint):
    print(f"Skipping: {metrics_path} exists for this checkpoint")
    return
  signature = checkpoint_signature(args.checkpoint)

  cfg = Config.fromfile(str(cfg_path))  # also runs cfg.custom_imports
  set_random_seed(args.seed)
  torch.backends.cudnn.benchmark = True

  cfg.model.pretrained = None
  cfg.model.train_cfg = None
  cfg.data.test.test_mode = True
  cfg.data.test.pop("samples_per_gpu", None)

  encoders = cfg.model.get("encoders") or {}
  fuser_cfg = cfg.model.get("fuser") or {}
  model_kind = "fusion" if encoders.get("camera") else "lidar"
  if fuser_cfg.get("type") == "GatedConvFuser":
    model_kind = f"gated-{fuser_cfg.get('gate_type', 'modality')}"
  camera_scale = float(fuser_cfg.get("camera_scale", 1.0))

  step = _weather_step(cfg.data.test.get("pipeline"))
  if step is None:
    raise RuntimeError("No WeatherDegradation step in data.test.pipeline")

  dataset = build_dataset(cfg.data.test)
  loader = build_dataloader(
      dataset,
      samples_per_gpu=1,
      workers_per_gpu=args.workers,
      dist=False,
      shuffle=False,
  )

  model = build_model(cfg.model, test_cfg=cfg.get("test_cfg"))
  if cfg.get("fp16", None) is not None:
    wrap_fp16_model(model)
  checkpoint = load_checkpoint(model, args.checkpoint, map_location="cpu")
  model.CLASSES = checkpoint.get("meta", {}).get("CLASSES", dataset.CLASSES)
  model = MMDataParallel(model.cuda(), device_ids=[0])

  print(
      f"Evaluating {len(dataset)} samples | model={model_kind} "
      f"camera_scale={camera_scale:g} "
      f"weather={step.get('weather')} "
      f"severity={step.get('severity')} modality={step.get('modality', 'both')} "
      f"seed={step.get('seed')}"
  )
  gate_weights = []
  fuser = getattr(model.module, "fuser", None)
  if fuser is not None and hasattr(fuser, "last_weights"):
    def _record(module, inputs, output):
      if module.last_weights is not None:
        gate_weights.append(module.last_weights)
    fuser.register_forward_hook(_record)

  start = time.time()
  outputs = single_gpu_test(model, loader)
  elapsed = time.time() - start

  if args.save_results:
    mmcv.dump(outputs, str(out_dir / "results.pkl"))

  metrics = dataset.evaluate(
      outputs, metric="bbox", jsonfile_prefix=str(out_dir / "nusc")
  )

  # The 10-class nuScenes mAP counts classes with no ground truth in the split
  # as AP 0 (mini_val lacks some classes), so also report mAP over the classes
  # that are actually present.
  gt_counts = gt_class_counts(dataset)
  class_ap = per_class_ap(out_dir / "nusc" / "metrics_summary.json")
  present = [c for c in dataset.CLASSES if gt_counts.get(c, 0) > 0]
  map_present = (
      sum(class_ap[c] for c in present) / len(present) if present else None
  )
  record = dict(
      config=str(cfg_path),
      checkpoint=str(args.checkpoint),
      checkpoint_signature=signature,
      model=model_kind,
      camera_scale=camera_scale,
      gate_w_cam=(sum(w[0] for w in gate_weights) / len(gate_weights)
                  if gate_weights else None),
      gate_w_lidar=(sum(w[1] for w in gate_weights) / len(gate_weights)
                    if gate_weights else None),
      dataset_version=getattr(dataset, "version", None),
      num_samples=len(dataset),
      weather=step.get("weather"),
      severity=step.get("severity"),
      modality=step.get("modality", "both"),
      degradation_seed=step.get("seed"),
      inference_seconds=round(elapsed, 1),
      mAP=metrics.get("object/map"),
      NDS=metrics.get("object/nds"),
      mAP_present=map_present,
      present_classes=present,
      gt_counts=gt_counts,
      class_ap=class_ap,
      metrics={k: float(v) for k, v in metrics.items()},
  )
  metrics_path.write_text(json.dumps(record, indent=2))
  missing = [c for c in dataset.CLASSES if c not in present]
  print(f"GT boxes per class: {gt_counts}")
  if missing:
    print(f"No ground truth in this split for: {missing}")
  if gate_weights:
    print(f"Mean gate weights: camera {record['gate_w_cam']:.3f}, "
          f"LiDAR {record['gate_w_lidar']:.3f}")
  print(
      f"mAP={record['mAP']:.4f} NDS={record['NDS']:.4f} "
      f"mAP_present={map_present:.4f} ({len(present)} classes) -> {metrics_path}"
  )


if __name__ == "__main__":
  main()
